    expect(lastExit().searchParams.get('plan')).toBe('standard');
    expect(consumeRunGateToken(sessionStore, 'standard')).toBe(true);
  });

  it('reviewStep on: Review exit issues no rungate token', async () => {
    fetchMe.mockResolvedValue(ME);
    visit(OK_QUERY);
    await mount(true);
    expect(consumeRunGateToken(sessionStore, 'standard')).toBe(false);
  });
"""
assert old in s
s=s.replace(old,new)
s=s.replace("import { sessionStore } from '@/flow/browserStorage/browserStorage';","import { sessionStore } from '@/flow/browserStorage/browserStorage';\nimport { consumeRunGateToken } from '@/flow/runGateToken/runGateToken';")
